-- API: GET /api/media | ListByActorAsync, one projection query with thumbnail/job LEFT JOINs
SELECT m.*, t.id AS thumbnail_id, t.status AS thumbnail_status, j.status AS thumbnail_job_status FROM media_objects m LEFT JOIN media_objects t ON t.source_media_id=m.id AND t.deleted_at IS NULL AND t.derivation_type='THUMBNAIL' LEFT JOIN media_background_jobs j ON j.subject_id=m.id AND j.job_type='THUMBNAIL_DERIVATION' WHERE m.uploaded_by=@actorId AND m.uploaded_by_type=@actorType AND m.source_media_id IS NULL AND m.deleted_at IS NULL AND (@mediaType IS NULL OR m.media_type=@mediaType) AND (@status IS NULL OR m.status=@status) AND (@cursorCreatedAt IS NULL OR m.created_at<@cursorCreatedAt OR (m.created_at=@cursorCreatedAt AND m.id<@cursorId)) ORDER BY m.created_at DESC,m.id DESC LIMIT @take;
